(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zi-sj-prepa-chir-j3-ide"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zi-sj-prepa-chir-j3-ide\",\n \"titre\": \"Préparation D.E (J) · J3 Chirurgie IDE\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 60,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n   \"sha256\": \"45110ca169c7b815e8c5983cb6aa915440763cce1306bb015109584afb42df7f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Chirurgie · Prépa D.E J3 (IDE)\",\n     \"slug\": \"prepa-chir-j3-ide\",\n     \"pages\": \"\",\n     \"count\": 60,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Chirurgie\",\n     \"source\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__0\",\n       \"num\": \"5\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Lors d’un AVP (accident de la voie publique), M. Zada, commerçant, est transféré à l’hôpital le plus proche ; le médecin traitant fait le constat suivant : des scalps et un hématome au niveau frontal, M. Zada est inconscient. Après une radio, le cliché montre une embarrure.\",\n       \"text\": \"Pour apprécier l’état de conscience de M. Zada le médecin traitant a utilisé le : donner la bonne réponse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Score de Silverman\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Score d’Apgar\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Score de Glasgow\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Score de Glasgow\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L’examen neurologique du traumatisé crânien apprécie la conscience par le score de Glasgow. Les scores de Silverman (détresse respiratoire du nouveau-né) et d’Apgar (vitalité à la naissance) concernent le nouveau-né.\\n\\nSource : NEUROCHIRURGIE L3, Traumatismes crâniens – II. Signes (score de Glasgow)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__1\",\n       \"num\": \"6\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Lors d’un AVP (accident de la voie publique), M. Zada, commerçant, est transféré à l’hôpital le plus proche ; le médecin traitant fait le constat suivant : des scalps et un hématome au niveau frontal, M. Zada est inconscient. Après une radio, le cliché montre une embarrure.\",\n       \"text\": \"Le score de Glasgow se réfère à ces trois paramètres suivants : lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La réponse oculaire (ouverture des yeux)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La douleur abdominale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La réponse verbale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La réponse motrice\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les céphalées\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Les vomissements\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. La réponse oculaire (ouverture des yeux) ; C. La réponse verbale ; D. La réponse motrice\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Le Glasgow cote l’ouverture des yeux (sur 4), la réponse verbale (sur 5) et la réponse motrice (sur 6). Douleur abdominale, céphalées et vomissements ne font pas partie du score.\\n\\nSource : NEUROCHIRURGIE L3, score de Glasgow (diapos 17 à 21)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__2\",\n       \"num\": \"7\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Lors d’un AVP (accident de la voie publique), M. Zada, commerçant, est transféré à l’hôpital le plus proche ; le médecin traitant fait le constat suivant : des scalps et un hématome au niveau frontal, M. Zada est inconscient. Après une radio, le cliché montre une embarrure.\",\n       \"text\": \"Vu le constat du médecin traitant, choisir le chiffre vraisemblable correspondant au score de Glasgow concernant M. Zada :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Score=5\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Score=10\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Score=14\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Score=12\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Score=5\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"M. Zada est inconscient : son score se situe dans la zone du traumatisme grave (Glasgow 3 à 8). Seul 5 entre dans cet intervalle ; 10 et 12 correspondent à un traumatisme modéré (9 à 12), 14 à un traumatisme bénin (13 à 15).\\n\\nSource : NEUROCHIRURGIE L3, niveaux de gravité (diapo 23)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__3\",\n       \"num\": \"8\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Lors d’un AVP (accident de la voie publique), M. Zada, commerçant, est transféré à l’hôpital le plus proche ; le médecin traitant fait le constat suivant : des scalps et un hématome au niveau frontal, M. Zada est inconscient. Après une radio, le cliché montre une embarrure.\",\n       \"text\": \"Les deux signes physiques suivants de M. Zada attestent d’un traumatisme crânien : lesquels\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L’hématome frontal\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les scalps\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les vomissements\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La sialorrhée\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les douleurs lombaires\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. L’hématome frontal ; B. Les scalps\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"L’examen du crâne recherche plaie, ecchymose et hématome ; le scalp est une plaie à lambeau du cuir chevelu. Ce sont les signes physiques constatés chez M. Zada. Les vomissements sont un signe fonctionnel, la sialorrhée et les lombalgies sont sans rapport.\\n\\nSource : NEUROCHIRURGIE L3, signes physiques (diapo 16) ; Cours de chirurgie traumatique et digestif (L2), lésions du cuir chevelu (diapo 107)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__4\",\n       \"num\": \"9\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Lors d’un AVP (accident de la voie publique), M. Zada, commerçant, est transféré à l’hôpital le plus proche ; le médecin traitant fait le constat suivant : des scalps et un hématome au niveau frontal, M. Zada est inconscient. Après une radio, le cliché montre une embarrure.\",\n       \"text\": \"Le traitement de l’embarrure de M. Zada sera fait par : donner la bonne réponse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Orthopédie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ostéosynthèse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Traitement médical\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Ostéosynthèse\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L’embarrure se traite chirurgicalement : le fragment enfoncé doit être remonté à son niveau initial puis suturé, toujours sous couverture antibiotique. Le traitement médical seul ne concerne que les contusions simples ; l’orthopédie (réduction externe, plâtre) ne s’applique pas à la voûte crânienne. Remarque : Le cours parle de « remonter l’embarrure et suturer » (geste chirurgical) sans employer le mot « ostéosynthèse ».\\n\\nSource : NEUROCHIRURGIE L3, IV. Traitement (diapo 38) ; Cours de chirurgie traumatique et digestif (L2), diapo 116\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__5\",\n       \"num\": \"10\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Lors d’un AVP (accident de la voie publique), M. Zada, commerçant, est transféré à l’hôpital le plus proche ; le médecin traitant fait le constat suivant : des scalps et un hématome au niveau frontal, M. Zada est inconscient. Après une radio, le cliché montre une embarrure.\",\n       \"text\": \"L’embarrure se définit comme étant :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Décollement d’un lambeau de cuir chevelu d’origine traumatique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une plaie béante du cuir chevelu\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un décollement d’un fragment de l’os crânien avec enfoncement dans la voûte crânienne suite à un traumatisme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Un décollement d’un fragment de l’os crânien avec enfoncement dans la voûte crânienne suite à un traumatisme\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L’embarrure est une fracture de la voûte avec enfoncement d’un fragment osseux vers l’intérieur du crâne. Le décollement d’un lambeau de cuir chevelu correspond au scalp (A) ; la plaie béante (B) est une lésion des parties molles, sans atteinte osseuse.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), lésions osseuses de la voûte : « fracture simple ou avec embarrure » (diapo 108) ; scalp = plaie à lambeau (diapo 107)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__6\",\n       \"num\": \"11\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Lors d’un AVP (accident de la voie publique), M. Zada, commerçant, est transféré à l’hôpital le plus proche ; le médecin traitant fait le constat suivant : des scalps et un hématome au niveau frontal, M. Zada est inconscient. Après une radio, le cliché montre une embarrure.\",\n       \"text\": \"S’appuyant sur les dires du médecin traitant, évaluer ce traumatisme crânien :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un traumatisme bénin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un traumatisme grave\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un traumatisme modéré\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Un traumatisme grave\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un patient inconscient avec embarrure a un Glasgow ≤ 8 : c’est un traumatisme crânien grave (Glasgow 3 à 8), qui relève de la réanimation.\\n\\nSource : Neurochirurgie (livret), p. 6 (traumatisme crânien grave) ; NEUROCHIRURGIE L3, diapo 23\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__7\",\n       \"num\": \"12\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces signes suivants indiquer deux concernant une fracture du fémur :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L’infection\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L’impotence fonctionnelle du membre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L’ankylose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La déformation du membre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. L’impotence fonctionnelle du membre ; D. La déformation du membre\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Dans la fracture de la diaphyse fémorale : douleur violente, impotence fonctionnelle absolue, et à l’inspection une déformation évidente (raccourcissement, crosse, rotation externe). L’infection et l’ankylose sont des complications, pas des signes de la fracture.\\n\\nSource : Traumatologie complet (chirurgie traumatologique et orthopédique), Fractures de la diaphyse du fémur – II. Étude clinique\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__8\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces organes suivants indiquer deux qui sont des organes pleins :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La vessie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le foie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La rate\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le colon\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L’intestin grêle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Le foie ; C. La rate\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Les viscères pleins sont le foie, la rate, les reins et le pancréas (leur rupture donne une hémorragie interne). Vessie, côlon et intestin grêle sont des viscères creux.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Contusions abdominales – anatomie pathologique (diapos 183-184)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__9\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces éléments suivants indiquer celui sur lequel est fixé l’appendice :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le caecum\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L’iléon\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le sigmoïde\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Le caecum\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L’appendice est un petit organe de 8 à 10 cm attaché au cæcum, juste au-dessous de la valvule iléo-cæcale.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Appendicite aiguë – II. Épidémiologie (diapo 210)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__10\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer le geste d’urgence à faire en cas de rétention aiguë des urines :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Donner les antibiotiques\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Donner les antiinflammatoires\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Poser une sonde vésicale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Donner de l’eau à boire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Poser une sonde vésicale\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le drainage vésical est une urgence : sondage urétral (ou ponction sus-pubienne), avec asepsie rigoureuse. Faire boire aggraverait la distension ; antibiotiques et anti-inflammatoires ne vident pas la vessie.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Rétention urinaire – IV. Traitement (diapo 307)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__11\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Donner deux complications immédiates lors d’une fracture ouverte :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rupture vasculaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Pseudarthrose\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rupture nerveuse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Cal-vicieux\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Douleur\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Rupture vasculaire ; C. Rupture nerveuse\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Les complications immédiates des fractures sont le choc, les lésions cutanées, des parties molles, vasculaires et nerveuses. Pseudarthrose et cal vicieux sont des complications secondaires/tardives ; la douleur est un signe, pas une complication.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Généralités sur les fractures – VIII. Complications\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__12\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’efficacité du traitement du cancer réside dans :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La précocité du diagnostic\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L’administration d’antibiotique massive\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L’administration d’anti douleur\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La précocité du diagnostic\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le pronostic des cancers dépend de la précocité du diagnostic : seul un diagnostic précoce permet un traitement chirurgical efficace ; les chances de guérison dépendent de la précocité du traitement. Antibiotiques et antalgiques ne traitent pas le cancer.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Cancer de l’estomac (généralités, pronostic) ; Cancer du rein (interventions infirmières)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__13\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’épiphyse inférieure d’un os long est aussi appelée :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Diaphyse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Métaphyse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Epiphyse distale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Epiphyse distale\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Un os long comprend une diaphyse (corps) et deux épiphyses (extrémités) reliées par les métaphyses. L’épiphyse inférieure, la plus éloignée de la racine du membre, est l’épiphyse distale ; la supérieure est l’épiphyse proximale. (explication hors cours du projet)\\n\\nSource : aucune source trouvée dans les cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__14\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour qu’il y ait une hernie abdominale il faut :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un abdomen volumineux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un mégacôlon\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un point de faiblesse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Un point de faiblesse\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La hernie est l’extériorisation d’un viscère à travers un point de faiblesse anatomique de la paroi abdominale ; le traitement vise d’ailleurs à « supprimer le point de faiblesse ».\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Hernies – introduction et V. Traitement (p. 98 et 108)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__15\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’ankylose est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une élongation du ligament\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une raideur de l’articulation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une rupture du tendon\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Une raideur de l’articulation\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L’ankylose est une raideur articulaire, séquelle tardive possible des fractures. L’élongation ligamentaire correspond à une entorse bénigne.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Généralités sur les fractures – complications tardives : « raideur articulaire (ankylose) »\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__16\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer deux buts du pansement parmi ceux-ci :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"But de désinfection\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"But de protection\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"But de rinçage\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"But de torsion\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"But d’ouverture\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. But de désinfection ; B. But de protection\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Devant toute plaie, la chronologie des soins est : découvrir, inspecter, désinfecter avec un antiseptique, assécher, appliquer le produit puis recouvrir. Le pansement sert donc à désinfecter et à protéger la plaie.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Plaies – VI. Conduite à tenir devant une plaie\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__17\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le petit bassin est aussi appelé :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L’abdomen supérieur\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le pelvis\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La ligne blanche\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Le pelvis\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L’abdomen comprend la cavité abdominale et le petit bassin ou pelvis.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Hernies – rappel anatomique (p. 99)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__18\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le mal de pott est une maladie qui touche : une réponse juste\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le cerveau\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les méninges\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La colonne vertébrale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les os iliaques\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La colonne vertébrale\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le mal de Pott est la tuberculose disco-vertébrale : il touche la colonne vertébrale (vertèbres et disques).\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Mal de Pott – définition (diapo 170)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__19\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas d’échec de la pose de la sonde vésicale en urgence dans une rétention aiguë des urines l’on recourt à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un traitement médical\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un traitement par voie orale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une ponction sus-pubienne\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Une ponction sus-pubienne\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Si le sondage vésical est impossible, il faut pratiquer une ponction sus-pubienne en respectant une asepsie rigoureuse.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Rétention urinaire (diapo 307) et Rétrécissement de l’urètre – conduite à tenir (diapo 317)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__20\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour le remplissage vasculaire (par les solutés) d’un brûlé grave l’on utilise :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La formule de ferry\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La règle de Baxter\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La formule de Gorgina\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. La règle de Baxter\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Pour le remplissage vasculaire du brûlé, la règle la plus utilisée est celle de Baxter : J1 = poids (kg) × 4 × SCB ; J2 = moitié de J1.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Brûlures 2 – 5.3 Réanimation hydroélectrolytique\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__21\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Toutes ces causes aboutissent à une occlusion mécanique, sauf une, laquelle ? :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Corps étrangers\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Torsion d’une anse (segment) intestinale sur elle-même\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dérèglement du système nerveux intestinal\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Invagination intestinale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Dérèglement du système nerveux intestinal\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le dérèglement du système nerveux intestinal (paralysie ou spasme) définit l’occlusion fonctionnelle. Les corps étrangers (obturation), le volvulus et l’invagination (strangulation) sont des causes mécaniques.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Occlusions intestinales aiguës – étiologies (p. 121-122)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__22\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les hernies suivantes, indiquer les deux qui sont des hernies de l’aine\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La hernie ventrale latérale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La hernie inguinale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La hernie crurale (fémorale)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La hernie de la ligne blanche\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La hernie ombilicale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. La hernie inguinale ; C. La hernie crurale (fémorale)\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Les hernies inguinales et crurales constituent les hernies de l’aine. Les hernies ombilicale, de la ligne blanche et ventrale latérale sont des hernies de la paroi antérieure ou latérale.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Hernies – introduction (p. 98)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__23\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les actes suivants, indiquer les deux possibles à effectuer en urgence, chez un patient qui souffre de rétention aiguë des urines\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L’adénomectomie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La ponction sus-pubienne\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le sondage urinaire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La cystectomie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La pose d’une vessie de glace\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. La ponction sus-pubienne ; C. Le sondage urinaire\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Le drainage vésical d’urgence se fait par sondage urétral ou par ponction sus-pubienne. L’adénomectomie traite la cause (adénome) à distance ; la cystectomie et la vessie de glace ne sont pas indiquées.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Rétention urinaire – IV. Traitement (diapo 307)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__24\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une des contre-indications de la pose de la sonde urinaire est la suivante :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L’infection\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La stérilité\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L’éjaculation précoce\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le cancer du rectum\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. L’infection\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Une infection urinaire ou urétrale aiguë (urétrite, prostatite) contre-indique le sondage, qui risque de disséminer les germes ; le cours insiste sur l’asepsie rigoureuse de tout geste urinaire. Stérilité, éjaculation précoce et cancer du rectum ne gênent pas le sondage. (explication partiellement hors cours du projet)\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Rétention urinaire (« respecter rigoureusement les règles d’asepsie ») ; Fractures du rachis – fonction urinaire\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__25\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le mal de pott affecte (touche) ces deux (02) parties du corps :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les vertèbres\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les bronches\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les disques intervertébraux\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La trachée\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le cerveau\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Les vertèbres ; C. Les disques intervertébraux\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Le mal de Pott est une lésion qui aboutit à la destruction simultanée des disques intervertébraux et des vertèbres.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Mal de Pott – définition et anatomie pathologique (diapos 170-171)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__26\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un malade souffrant de douleur abdominale localisée dans la fosse iliaque droite de survenue brutale. Il peut s’agir de : une seule réponse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hernie de la ligne blanche\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Appendicite aigue\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Douleur néphrétique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Appendicite aigue\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L’appendicite est la cause la plus courante d’inflammation aiguë du cadran inférieur droit ; son diagnostic positif repose sur la douleur de la fosse iliaque droite.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Appendicite aiguë (diapos 210 et 216)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__27\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Déterminer deux diagnostics différentiels de l’appendicite aigue :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hépatite\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Pancréatite aigue\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"GEU (grosse extra utérine)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Salpingite\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Rectorragie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. GEU (grosse extra utérine) ; D. Salpingite\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Chez la femme, le cours cite parmi les diagnostics différentiels la salpingite droite et la grossesse extra-utérine droite (rupture de grossesse tubaire). Hépatite, pancréatite et rectorragie ne sont pas citées.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Appendicite aiguë – VIII. Diagnostic différentiel (p. 116-117)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__28\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans quel cadran de l’abdomen est situé le foie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L’épigastre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L’hypogastre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L’hypochondre droit\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La fosse iliaque\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. L’hypochondre droit\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dans la division clinique de l’abdomen en 9 régions, l’hypochondre droit contient le foie ; l’épigastre contient surtout l’estomac, l’hypogastre la vessie et les organes génitaux.\\n\\nSource : Appareil digestif L1 2023, 4.3 Division clinique de l’abdomen\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__29\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les membres supérieurs appartiennent au :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Squelette principal\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Squelette appendiculaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Squelette axial\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Squelette appendiculaire\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le squelette se divise en squelette axial (tête et tronc) et squelette appendiculaire (les membres supérieurs et inférieurs).\\n\\nSource : Anatomie – Ostéologie complet, définition du squelette et chap. II\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__30\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La prise en charge d’une fracture simple dans un EPHR se réalise par ces deux (02) actes :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un pansement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une réduction\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une contention (immobilisation)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une incision\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Une ouverture du foyer de fracture\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Une réduction ; C. Une contention (immobilisation)\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Le traitement orthopédique d’une fracture comporte la réduction (remettre les fragments en place) puis la contention (maintien jusqu’à la formation du cal). Incision et ouverture du foyer relèvent de l’ostéosynthèse chirurgicale.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Généralités sur les fractures – VI. Traitement\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__31\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après la consolidation de la fracture il faut réaliser une :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rééducation fonctionnelle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Assistance ventilatoire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Ponction du trait de fracture\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Rééducation fonctionnelle\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dès consolidation de la fracture, il faut commencer la rééducation.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Généralités sur les fractures – 6.1 Traitement orthopédique\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__32\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une des contre-indications de la pose d’une sonde urinaire est la suivante :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le vertige\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La gonococcie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les vomissements\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. La gonococcie\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L’urétrite gonococcique (blennorragie) est une infection de l’urètre : sonder risque de propager l’infection et de léser un urètre inflammatoire ; elle est d’ailleurs la première cause de rétrécissement urétral. Vertige et vomissements ne contre-indiquent pas le sondage. (explication partiellement hors cours du projet)\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Rétrécissement de l’urètre – étiologie (diapo 313)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__33\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le choc septique est aussi appelé :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Choc hypovolémique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Choc microbien (bactérien)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Choc traumatique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Choc microbien (bactérien)\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours décrit le « choc bactérien ou choc septique », dû aux septicémies (germes Gram négatif, toxines bactériennes).\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Chocs traumatiques – II. Étiologies 2-4 (diapo 123)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__34\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le rein fait partie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Du bas appareil urinaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Du milieu de l’appareil urinaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Du haut appareil urinaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Du haut appareil urinaire\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le haut appareil urinaire comprend les reins et leurs voies excrétrices (cavités, uretères) ; le bas appareil comprend la vessie et l’urètre. Le cours parle du retentissement de la rétention « sur le haut appareil (distension des cavités, insuffisance rénale) ».\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Rétention chronique d’urines – physiopathologie (diapo 303)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__35\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’un des diagnostics différentiels de l’appendicite est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Douleur dans l’hypochondre gauche\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une infection de l’ovaire droit\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une douleur épigastrique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Une infection de l’ovaire droit\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez la femme, une annexite droite (infection de l’ovaire/trompe droite), un pyo-ovaire droit ou une torsion de kyste ovarien droit sont des diagnostics différentiels, car la douleur siège aussi en fosse iliaque droite.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Appendicite – diagnostic différentiel chez la femme (diapo 217) ; Prise en charge infirmière des pathologies chirurgicales L2 2025, p. 117\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__36\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’hydrocèle est un épanchement liquidien :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dans le scrotum\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dans le canal inguinal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dans l’utérus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Dans le scrotum\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L’hydrocèle est un épanchement liquidien séreux entre les deux feuillets de la vaginale, membrane qui entoure le testicule dans la bourse (scrotum).\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Hydrocèle – définition (diapo 321)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__37\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La hernie non compliquée est aussi appelée :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hernie étranglée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hernie non étranglée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hernie douloureuse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Hernie non étranglée\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La principale complication de la hernie est l’étranglement ; une hernie non compliquée est donc non étranglée (indolore, réductible, impulsive à la toux).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Hernies – IV. Diagnostic (p. 106-107)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__38\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La hernie étranglée est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Irréductible\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Réductible\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dégonflable\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Irréductible\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la hernie étranglée, la tuméfaction est dure, tendue, douloureuse, irréductible, non impulsive et non expansive à la toux. Remarque : Dans le sujet, les options sont lettrées A, B puis D (pas de C).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Hernies – 4.2 Hernie compliquée (p. 108)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__39\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’appendice peut occuper aussi cette position :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Sus hépatique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sus splénique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Latérocaecale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Latérocaecale\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L’appendice, fixé au cæcum, peut occuper plusieurs positions autour de celui-ci (latéro-cæcale, rétro-cæcale, pelvienne, méso-cœliaque, sous-hépatique). Il ne peut pas se trouver au-dessus du foie ni au-dessus de la rate. Remarque : Le cours cite les positions rétro-cæcale, méso-cœliaque, pelvienne et sous-hépatique ; la position « latéro-cæcale » n’y est pas nommée telle quelle.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Appendicite – formes topographiques (p. 116)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__40\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’anorexie, les vomissements alimentaires et la constipation sont des signes annonciateurs ou prodromes de l’appendicite aigue\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Les prodromes de l’appendicite sont l’anorexie, les nausées, les vomissements (surtout chez l’enfant) ; la constipation est plus fréquente que la diarrhée.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Appendicite – V. Manifestations cliniques a) Prodromes (diapo 213)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__41\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le volvulus intestinal et l’invagination intestinale sont des causes mécaniques de l’occlusion intestinale aigue\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Volvulus (torsion d’une anse) et invagination (télescopage) réalisent une strangulation, mécanisme des occlusions mécaniques.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Occlusions – 1.1 Occlusions mécaniques (p. 122)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__42\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La hernie ombilicale est un épanchement liquidien dans l’ombilic\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Une hernie est l’extériorisation d’un viscère (intestin, épiploon) à travers un point de faiblesse de la paroi, ici l’ombilic ; ce n’est pas un épanchement liquidien (définition qui évoque l’hydrocèle).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Hernies – définition (p. 98)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__43\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’adénome de la prostate est une affection bénigne qui se manifeste par une hypertrophie de la prostate\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. L’adénome de la prostate est une tumeur bénigne qui se traduit par une hyperplasie et une hypertrophie de la glande prostatique.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Adénome de la prostate – définition (diapo 286)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__44\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Plus le score de Glasgow est élevé plus l’état du malade est grabataire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le score de Glasgow va de 3 (aucune réponse) à 15 (conscience normale) : 3 à 8 = traumatisme grave, 13 à 15 = traumatisme bénin. Un score élevé traduit donc un meilleur état de conscience.\\n\\nSource : NEUROCHIRURGIE L3, diapos 17 à 23\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__45\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le défaut de sécrétion de testostérone est l’une des causes de la cryptorchidie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. La descente du testicule est commandée par les hormones mâles (testostérone) ; la cryptorchidie est due à un défaut de sécrétion de ces hormones ou à un obstacle anatomique.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Anomalies de la descente du testicule (diapo 318)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__46\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les occlusions intestinales fonctionnelles ont pour synonymes les occlusions mécaniques\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Les occlusions fonctionnelles (dérèglement nerveux : paralysie, spasme) s’opposent aux occlusions mécaniques (obstacle organique : obturation, strangulation).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Occlusions – étiologies (p. 121-122)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__47\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les vomissements fécaloïdes évoquent une occlusion haute\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Les vomissements sont d’abord alimentaires puis bilieux et ne deviennent fécaloïdes qu’après un certain temps d’évolution ; dans l’occlusion haute (grêle) les vomissements sont précoces, abondants et bilieux.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Occlusions – signes fonctionnels et diagnostic du siège (p. 123-125)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__48\",\n       \"num\": \"53\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fracture ouverte véritable est la fracture ouverte de dedans en dehors\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Le cours distingue la fracture ouverte de dedans en dehors (peau lésée par un fragment osseux) et la fracture ouverte véritable, ouverte de dehors en dedans (le traumatisme lèse la peau puis l’os).\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Généralités sur les fractures – 5.2 Fracture ouverte\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__49\",\n       \"num\": \"54\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lors de la surveillance d’un traumatisé, l’accélération du pouls et une hypotension artérielle atteste d’un état de choc\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Tachycardie, pouls accéléré voire imprenable et chute tensionnelle sont des signes d’état de choc ; chez le fracturé du fémur, « pâleur, accélération du pouls, baisse de tension » traduisent le choc.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Chocs traumatiques – symptomatologie (diapos 124-125)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__50\",\n       \"num\": \"55\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La radiographie est par excellence le diagnostic positif d’une fracture diaphysaire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. La radiographie seule permet de confirmer le diagnostic de fracture et d’en préciser le type et le déplacement ; pour le fémur, deux clichés face et profil sont indispensables.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Généralités sur les fractures – IV. Examens complémentaires\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__51\",\n       \"num\": \"56\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’étranglement herniaire peut occasionner une occlusion intestinale aigue\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. L’étranglement herniaire s’accompagne de vomissements et d’arrêt des matières et des gaz (signes d’occlusion haute si le grêle est étranglé) ; la hernie étranglée est une cause d’occlusion recherchée à l’examen.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Hernies – 4.2 (p. 107-108) ; Occlusions – examen (p. 124)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__52\",\n       \"num\": \"57\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le globe vésical évoque une rétention aigue des urines\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Dans la rétention aiguë, on trouve un globe vésical : masse hypogastrique pouvant remonter jusqu’à l’ombilic, douloureuse à la palpation.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Rétention aiguë d’urines – signes physiques (diapo 302)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__53\",\n       \"num\": \"58\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le choc opératoire fait partie des choc traumatiques\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. « Le choc opératoire est une variété de choc traumatique. »\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Chocs traumatiques – II. Étiologies 2-1 (diapo 122)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__54\",\n       \"num\": \"59\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le choc hypovolémique chez un traumatisé de la voie publique évoque une hémorragie abondante\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. L’hémorragie (hémopéritoine, hémothorax, gros hématomes) est la première cause de choc hypovolémique chez le traumatisé.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Chocs traumatiques – 2-2 Choc hypovolémique (diapo 122)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__55\",\n       \"num\": \"60\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un anthrax présente les signes cardinaux de l’inflammation\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. L’anthrax se présente comme une plaque indurée, rouge, chaude et douloureuse, puis un placard rouge-violacé, saillant, très douloureux : on retrouve les signes de l’inflammation (rougeur, chaleur, douleur, tuméfaction).\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Anthrax – signes cliniques\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__56\",\n       \"num\": \"61\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un anthrax est un ensemble de furoncles\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. L’anthrax est une agglomération de furoncles reliés entre eux par une suppuration du derme.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Anthrax – définition\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__57\",\n       \"num\": \"62\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un abcès froid présente la rougeur, la tuméfaction, la douleur, chaleur\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. L’abcès froid est une collection purulente chronique caractérisée par sa formation lente et l’absence des signes cardinaux de l’inflammation (ces signes définissent l’abcès chaud).\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Abcès froid – définition\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__58\",\n       \"num\": \"63\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La polydactylie est aussi appelée la syndactylie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. La polydactylie est une augmentation du nombre des doigts ; la syndactylie est l’union de deux ou plusieurs doigts (doigts palmés).\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Malformations congénitales des membres\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j3-ide__59\",\n       \"num\": \"64\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La toux chronique est l’une des causes de la hernie inguinale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. La toux chronique est un facteur herniogène (elle augmente la pression intra-abdominale), comme le travail de force, la constipation chronique ou la dysurie.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Hernies – III. Facteurs favorisants (p. 106)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
